-- ============================================================
-- RUAI TV — Database Schema & Data Seeder
-- Database Name: ruai_tv
-- Host: localhost (XAMPP MySQL)
-- ============================================================

CREATE DATABASE IF NOT EXISTS `ruai_tv` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `ruai_tv`;

-- --------------------------------------------------------
-- Table structure for table `programs`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `programs`;
CREATE TABLE `programs` (
  `id` VARCHAR(64) NOT NULL,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `category` ENUM('berita', 'non-news', 'kerja-sama') NOT NULL DEFAULT 'berita',
  `category_label` VARCHAR(100) DEFAULT NULL,
  `status` ENUM('aktif', 'arsip') NOT NULL DEFAULT 'aktif',
  `format` VARCHAR(100) DEFAULT '—',
  `duration` VARCHAR(50) DEFAULT '—',
  `description` TEXT DEFAULT NULL,
  `thumbnail_url` VARCHAR(255) DEFAULT NULL,
  `promo_video_url` VARCHAR(255) DEFAULT NULL,
  `youtube_live_url` VARCHAR(255) DEFAULT NULL,
  `schedule_json` LONGTEXT DEFAULT NULL,
  `featured` TINYINT(1) DEFAULT 0,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

