INSERT INTO `programs` (`id`, `title`, `slug`, `category`, `category_label`, `status`, `format`, `duration`, `description`, `thumbnail_url`, `promo_video_url`, `youtube_live_url`, `schedule_json`, `featured`) VALUES
('warta-ruai', 'Warta Ruai', 'warta-ruai', 'berita', 'Program Berita', 'aktif', 'Berita', '60 Menit', 'Paket buletin berita hasil liputan harian pada peristiwa dan isu aktual yang terjadi di Pontianak dan sekitarnya, serta Kalimantan Barat pada umumnya. Tayang tiga kali sehari — pagi, siang, dan malam — untuk memastikan pemirsa selalu mendapatkan informasi terkini.', 'assets/images/programs/Warta-Ruai.png', 'https://www.youtube.com/embed/live_stream?channel=UCruaitv', 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": true, "label": "PAGI", "time": "07.00 – 08.00 WIB", "days": "Senin - Sabtu"}, "siang": {"active": true, "label": "SIANG", "time": "13.00 – 14.00 WIB", "days": "Senin - Sabtu"}, "malam": {"active": true, "label": "MALAM", "time": "19.00 – 20.00 WIB", "days": "Senin - Sabtu"}}', 1),
('ruai-sepekan', 'Ruai Sepekan', 'ruai-sepekan', 'berita', 'Program Berita', 'aktif', 'Buletin Berita', '30 Menit', 'Rangkuman berita terhangat atau berita-berita utama selama sepekan dari Warta Ruai. Disajikan secara interaktif di mana publik memiliki ruang untuk mengomentari, mempertanyakan, dan memberikan opini terhadap materi berita atau permasalahan yang menjadi isi berita.', 'assets/images/programs/Ruai-Sepekan.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": true, "label": "MALAM", "time": "19.30 – 20.00 WIB", "days": "Minggu"}}', 0),
('warta-warganet', 'Warta Warganet', 'warta-warganet', 'berita', 'Program Berita', 'aktif', 'Buletin Berita', '30 Menit', 'Acara yang digagas untuk memberi ruang dan menghargai WargaNet di Media Arustama. Memberikan apresiasi atas karya spontanitas maupun terencana terhadap segala kekayaan adat budaya, lingkungan, alam dan bahkan kesenjangan sosial yang tertangkap mata kamera Warganet.', 'assets/images/programs/WargaNet.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": true, "label": "SIANG", "time": "18.30 – 19.00 WIB", "days": "Selasa & Jumat"}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('rumah-kita', 'Rumah Kita', 'rumah-kita', 'berita', 'Program Berita', 'aktif', 'Talkshow / Podcast', '60 Menit', 'Program bincang-bincang/podcast inspiratif yang mengangkat kisah hidup, dedikasi, perjuangan, serta kiprah para tokoh publik, pemuka agama, pelaku seni, maupun individu inspiratif di Kalimantan Barat dalam melayani dan memberikan dampak positif bagi komunitas serta masyarakat luas.', 'assets/images/programs/Rumah-Kita.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": true, "label": "MALAM", "time": "20.05 – 21.05 WIB", "days": "Senin"}}', 0),
('forum-ruai', 'Forum Ruai', 'forum-ruai', 'berita', 'Program Berita', 'aktif', 'Talkshow', '60 Menit', 'Forum Ruai Adalah ruang diskusi kritis yang sehat untuk memaparkan suatu masalah yang sedang terjadi maupun yang mungkin akan terjadi, membedah dari berbagai sudut pandang intelektualitas dengan kritis dan professional dan selalu memberi rekomendasi diakhir acara.', 'assets/images/programs/Forum-Ruai.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": true, "label": "MALAM", "time": "20.05 – 21.05 WIB", "days": "Kamis"}}', 0),
('special-dialog', 'Special Dialog', 'special-dialog', 'berita', 'Program Berita', 'aktif', 'Talkshow', '60 Menit', 'Program dialog mendalam yang membahas isu-isu strategis politik, ekonomi, sosial, dan budaya bersama narasumber terpilih dari kalangan pejabat, pakar, dan tokoh masyarakat Kalimantan Barat.', 'assets/images/programs/Spesial-Dialog.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": true, "label": "PAGI", "time": "Tentatif / Kondisioanl", "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('kilas-ruai', 'Kilas Ruai', 'kilas-ruai', 'berita', 'Program Berita', 'arsip', 'Breaking News', '—', 'Kilas ruai adalah ruang aktual penyajian berita dari berbagai jenis peristiwa yang terjadi disetiap redaksi mendapat informasi yang langsung direspon dengan cepat, cekat dan profesional tanpa mengurangi nilai kebenaran peristiwa. Selalu mengacu kepada 5W+1H', 'assets/images/programs/Kilas-Ruai.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": true, "label": "PAGI", "time": "10.00 WIB", "days": "Senin - Sabtu"}, "siang": {"active": true, "label": "SORE", "time": "15.00 WIB", "days": "Senin - Sabtu"}, "malam": {"active": true, "label": "SORE", "time": "17.00 WIB", "days": "Senin - Sabtu"}}', 0),
('gong-ruai', 'Gong Ruai (On Target)', 'gong-ruai', 'berita', 'Program Berita', 'arsip', 'News Feature', '30 Menit', 'Acara Gong Ruai adalah ruai dokumenter reporting indept terhadap suatu kasus atau masalah yang sedang menjadi perhatian publik atau masyarakat tertentu seperti isu pengukuhan dan atau pengakuan akan hak masyarakat adat. Laporannya lebih dalam, tajam, kritis dan solutif. Menyajikan data primer, data sekunder dan sudut pandang dari sejumlah pakar dan pihak-pihak yang terlibat dalam topik dokumenter.', 'assets/images/programs/Warta-Ruai.png', NULL, NULL, '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('warta-ruai-3-bahasa', 'Warta Ruai 3 Bahasa', 'warta-ruai-3-bahasa', 'berita', 'Program Berita', 'arsip', 'Program Berita / Talkshow', '—', 'Program berita unggulan Ruai TV yang disajikan dalam lima bahasa daerah Kalimantan Barat, menjangkau berbagai komunitas etnis di seluruh pelosok Kalbar.', 'assets/images/programs/Warta-Ruai.png', NULL, NULL, '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('warta-credit-union', 'Warta Credit Union', 'warta-credit-union', 'berita', 'Program Berita', 'arsip', '—', '—', 'Jendela berita ekonomi kerakyatan berbasis koperasi simpan pinjam (Credit Union) di Kalimantan Barat, salah satu gerakan CU terbesar di Indonesia.', 'assets/images/programs/Warta-Ruai.png', NULL, NULL, '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('slada-video-klip', 'Slada Video Klip', 'slada-video-klip', 'non-news', 'Non-News', 'aktif', 'Hiburan', '—', 'Program hiburan yang menayangkan video klip musik pilihan, menemani pemirsa Ruai TV dengan sajian musik terbaik dari berbagai genre.', 'assets/images/programs/Slada.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('galeri-khatulistiwa', 'Galeri Khatulistiwa', 'galeri-khatulistiwa', 'non-news', 'Non-News', 'arsip', 'Dokumenter', '—', 'Tayangan dokumenter yang menampilkan keindahan alam dan budaya Kalimantan Barat serta Nusantara dalam format visual yang memukau.', 'assets/images/programs/Borneo-Rawa-Island.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('slada-reguler', 'Slada Reguler', 'slada-reguler', 'non-news', 'Non-News', 'arsip', 'Hiburan', '—', 'Senandung Lagu Daerah (SLADA) reguler — program yang melestarikan dan memopulerkan lagu-lagu daerah Kalimantan Barat dalam format tayangan yang modern.', 'assets/images/programs/Slada.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('slada-week-end', 'Slada Week End', 'slada-week-end', 'non-news', 'Non-News', 'arsip', 'Hiburan', '—', 'Edisi akhir pekan dari program Senandung Lagu Daerah (SLADA) yang hadir dengan nuansa lebih santai dan pilihan lagu yang lebih beragam untuk menemani waktu weekend keluarga.', 'assets/images/programs/Slada.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('kapuas-karaoke', 'Kapuas (Karaoke Sampai Puas)', 'kapuas-karaoke', 'non-news', 'Non-News', 'arsip', 'Hiburan', '—', 'Program interaktif karaoke yang mengundang pemirsa untuk ikut bernyanyi bersama dan menikmati lagu-lagu favorit dalam format hiburan yang menyenangkan.', 'assets/images/programs/Slada.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('penyejuk-iman', 'Penyejuk Iman', 'penyejuk-iman', 'non-news', 'Non-News', 'arsip', 'Religi', '—', 'Program rohani yang menghadirkan ceramah, renungan, dan tayangan inspiratif untuk memperkuat keimanan dan spiritualitas pemirsa Ruai TV.', 'assets/images/programs/Warta-Ruai.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('masakan-istimewa', 'Masakan Istimewa (Maskis)', 'masakan-istimewa', 'non-news', 'Non-News', 'arsip', 'Kuliner', '—', 'Program kuliner yang mengeksplorasi kekayaan cita rasa masakan khas dan istimewa Kalimantan Barat, menghadirkan resep, teknik memasak, dan cerita di balik hidangan tradisional maupun modern.', 'assets/images/programs/Warta-Ruai.png', NULL, NULL, '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
