('voa-warung-kita', 'VOA — Warung Kita', 'voa-warung-kita', 'kerja-sama', 'Kerja Sama', 'aktif', 'Feature', '—', 'Program kerja sama dengan VOA yang menghadirkan konten feature khas kearifan lokal dan budaya Nusantara dalam sudut pandang internasional VOA.', 'assets/images/programs/VOA-Warung-Kita.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('borneo-rawa-island', 'Borneo Rawa Island', 'borneo-rawa-island', 'kerja-sama', 'Kerja Sama', 'aktif', 'Dokumenter', '—', 'Program dokumenter hasil kerja sama yang mengeksplorasi kekayaan alam, ekosistem gambut, dan kehidupan di pulau Borneo/Kalimantan.', 'assets/images/programs/Borneo-Rawa-Island.png', NULL, 'https://www.youtube.com/@ruaitv/live', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
('cbn-solusi', 'CBN — Solusi', 'cbn-solusi', 'kerja-sama', 'Kerja Sama', 'aktif', 'Talkshow', '—', 'Program talkshow hasil kerja sama dengan CBN yang menghadirkan solusi praktis untuk berbagai permasalahan kehidupan sehari-hari.', 'assets/images/programs/CBN-Solusi.png', NULL, 'https://www.youtube.com/', '{"pagi": {"active": false, "label": "PAGI", "time": null, "days": null}, "siang": {"active": false, "label": "SIANG", "time": null, "days": null}, "malam": {"active": false, "label": "MALAM", "time": null, "days": null}}', 0),
